<template>
  <div class="gate-wrap">
    <div class="gate-divider"></div>
    <button type="button" class="gate-button" :disabled="loading" @click="enter">
      {{ loading ? '正在接入…' : '登 录' }}
    </button>
  </div>
</template>

<script setup lang="ts">
import { ref } from 'vue';

const loading = ref(false);

async function enter() {
  if (loading.value) return;
  loading.value = true;
  try {
    await setChatMessages([{ message_id: 0, swipe_id: 1 }]);
  } catch (error) {
    console.error('切换到身份创建失败', error);
    toastr.error('切换失败，请尝试手动左右滑动切换开场白');
    loading.value = false;
  }
}
</script>

